User stories:
[{"id": "US1", "description": "Jako Pacjent chcę przeglądać dostępne terminy u wybranego specjalisty w czytelnym kalendarzu aktualizowanym w czasie rzeczywistym, aby szybko znaleźć i zarezerwować odpowiadający mi termin wizyty."}, {"id": "US2", "description": "Jako Pacjent chcę dokonać rezerwacji wizyty w maksymalnie 3 krokach z natychmiastowym potwierdzeniem, aby mieć pewność że termin został zarezerwowany i nie zostanie zajęty przez innego użytkownika."}, {"id": "US3", "description": "Jako Pacjent chcę zobaczyć jasno sformułowane zasady anulowania (okno czasowe, ewentualne opłaty) przed potwierdzeniem rezerwacji i wyrazić na nie zgodę, aby uniknąć nieoczekiwanych konsekwencji przy późniejszym anulowaniu."}, {"id": "US4", "description": "Jako Pacjent chcę anulować rezerwację w dozwolonym oknie czasowym bez dodatkowych opłat i otrzymać potwierdzenie anulowania oraz automatyczny zwrot kaucji, aby móc elastycznie zarządzać swoimi wizytami bez ryzyka finansowego."}, {"id": "US5", "description": "Jako Pacjent chcę otrzymać natychmiastowe powiadomienie (push i/lub email) gdy specjalista zmieni lub odwoła mój zarezerwowany termin, wraz z propozycją alternatywnego terminu lub możliwością bezkosztowego anulowania, aby móc szybko podjąć decyzję o dalszym postępowaniu."}, {"id": "US6", "description": "Jako Pacjent chcę przeglądać historię moich rezerwacji oraz eksportować moje dane osobowe na żądanie, aby mieć pełną kontrolę nad swoimi informacjami zgodnie z przysługującymi mi prawami RODO."}, {"id": "US7", "description": "Jako Specjalista chcę zarządzać swoim grafikiem dostępności z możliwością masowej edycji (ustawienie urlopu, kopiowanie wzorca tygodniowego, definiowanie przerw), aby efektywnie planować pracę bez konieczności ręcznego edytowania każdego slotu."}, {"id": "US8", "description": "Jako Specjalista chcę modyfikować istniejące sloty w grafiku nawet gdy mają przypisane rezerwacje, z automatycznym powiadomieniem pacjentów o zmianie i propozycją alternatywy, aby móc reagować na nieprzewidziane okoliczności bez ręcznego kontaktowania się z każdym pacjentem."}, {"id": "US9", "description": "Jako Specjalista chcę synchronizować mój grafik z zewnętrznym kalendarzem (Google Calendar, iCal) dwukierunkowo, aby uniknąć konfliktów między rezerwacjami na platformie a moimi innymi zobowiązaniami zawodowymi."}, {"id": "US10", "description": "Jako Specjalista chcę logować się do systemu z obowiązkowym uwierzytelnianiem dwuskładnikowym (MFA), aby moje konto i dane moich pacjentów były chronione przed nieautoryzowanym dostępem."}, {"id": "US11", "description": "Jako Specjalista chcę przeglądać listę moich nadchodzących rezerwacji z możliwością filtrowania i sortowania, aby efektywnie przygotowywać się do wizyt i zarządzać swoim czasem pracy."}, {"id": "US12", "description": "Jako Administrator chcę autoryzować wyjątki od reguł konfliktów rezerwacji z obowiązkowym uzasadnieniem rejestrowanym w logu audytowym, aby zachować kontrolę nad odstępstwami od standardowych reguł przy jednoczesnej możliwości obsługi uzasadnionych przypadków szczególnych."}, {"id": "US13", "description": "Jako Administrator chcę zarządzać polityką anulowania (okno czasowe, wysokość kaucji, procedura wyjątków) poprzez panel konfiguracyjny bez modyfikacji kodu, aby dostosowywać zasady platformy do zmieniających się wymagań biznesowych i prawnych."}, {"id": "US14", "description": "Jako Administrator chcę przeglądać panel raportowy z KPI biznesowymi (wykorzystanie terminów, wskaźnik no-show, przychody, aktywni użytkownicy, konwersja rezerwacji), aby podejmować decyzje biznesowe oparte na danych i monitorować kondycję platformy."}, {"id": "US15", "description": "Jako Administrator chcę przeglądać szczegółowe logi audytowe wszystkich krytycznych operacji (rezerwacje, anulowania, modyfikacje grafiku, zmiany uprawnień) z możliwością filtrowania po użytkowniku, roli, typie operacji i przedziale czasowym, aby wykrywać nadużycia i spełniać wymogi regulacyjne."}, {"id": "US16", "description": "Jako Administrator chcę zarządzać kontami użytkowników i specjalistów (tworzenie, blokowanie, zmiana ról, resetowanie MFA), aby utrzymywać porządek w bazie użytkowników i reagować na incydenty bezpieczeństwa."}, {"id": "US17", "description": "Jako Pacjent chcę przejść prosty onboarding wyjaśniający funkcje systemu, zasady rezerwacji i anulowania oraz moje prawa jako użytkownika, aby od razu sprawnie korzystać z platformy bez potrzeby kontaktowania się z pomocą techniczną."}, {"id": "US18", "description": "Jako Pacjent chcę wnioskować o anulowanie rezerwacji poza dozwolonym oknem czasowym z podaniem uzasadnienia, a system automatycznie przekaże wniosek do autoryzacji administratora i poinformuje mnie o decyzji, aby w wyjątkowych sytuacjach móc skorzystać z elastyczności platformy."}, {"id": "US19", "description": "Jako Specjalista chcę definiować różne typy wizyt z różnym czasem trwania i dostępnością (np. konsultacja 30 min, badanie 60 min, wizyta online), aby precyzyjnie zarządzać swoim grafikiem i oferować pacjentom odpowiednie opcje rezerwacji."}, {"id": "US20", "description": "Jako Administrator chcę otrzymywać automatyczne alerty gdy dostępność systemu spadnie poniżej progu SLA lub gdy zostanie wykryta anomalia w liczbie operacji (potencjalny atak lub błąd systemowy), aby natychmiast reagować na incydenty i minimalizować ich wpływ na użytkowników."}]

