    },
    {
      "id": "NFR6",
      "description": "System musi szyfrować dane w tranzycie i w spoczynku, w szczególności dane osobowe, dane wizyt, identyfikatory oraz wrażliwe elementy logów i kopii zapasowych."
    },
    {
      "id": "NFR7",
      "description": "System musi zapewniać pełną audytowalność operacji biznesowych i bezpieczeństwa, w tym rezerwacji, anulowań, wyjątków, zmian grafiku, zmian uprawnień oraz działań uprzywilejowanych, z zachowaniem niezmienialności śladu audytowego."
    },
    {
      "id": "NFR8",
      "description": "System musi zapewniać obserwowalność poprzez logi, metryki, identyfikatory korelacyjne i alerty umożliwiające diagnozowanie incydentów, reklamacji oraz błędów współbieżności."
    },
    {
      "id": "NFR9",
      "description": "Interfejs użytkownika musi być responsywny, dostępny i zgodny z dobrymi praktykami dostępności cyfrowej dla kluczowych procesów przeglądania terminów, rezerwacji, anulowania i obsługi zmian."
    },
    {
      "id": "NFR10",
      "description": "System musi prezentować komunikaty i stany interfejsu w sposób spójny, jednoznaczny i zrozumiały dla użytkownika końcowego, także w scenariuszach błędów, konfliktów i wyjątków."
    },
    {
      "id": "NFR11",
      "description": "System musi minimalizować ujawnianie danych o innych użytkownikach i nie może eksponować nadmiarowych informacji w widokach dostępności, komunikatach błędów, powiadomieniach ani interfejsach API."
    },
    {
      "id": "NFR12",
      "description": "Publiczne interfejsy systemu muszą być chronione przed nadużyciami poprzez rate limiting, walidację wejścia, ochronę przed enumeracją identyfikatorów oraz mechanizmy ograniczające automatyzację i spam rezerwacyjny."
    },
    {
      "id": "NFR13",
      "description": "Operacje rezerwacji, anulowania i zmian grafiku muszą być idempotentne lub równoważnie odporne na ponowienie żądania tak, aby awarie częściowe nie prowadziły do niespójnych stanów biznesowych."
    },
    {
      "id": "NFR14",
      "description": "System musi poprawnie obsługiwać strefy czasowe, zmiany czasu oraz synchronizację zegarów przy wyznaczaniu terminów wizyt, okien anulowania i znaczników audytowych."
    },
    {
      "id": "NFR15",
      "description": "Reguły biznesowe dotyczące konfliktów rezerwacji, wyjątków i polityk anulacji muszą być konfigurowalne bez konieczności częstych zmian kodu aplikacyjnego oraz możliwe do wersjonowania i audytu."
    },
    {
      "id": "NFR16",
      "description": "Architektura rozwiązania musi wspierać utrzymywalność i testowalność poprzez wyraźne granice odpowiedzialności komponentów, możliwość testowania współbieżności oraz deterministyczną obsługę czasu w testach."
    },
    {
      "id": "NFR17",
      "description": "System musi spełniać wymagania ochrony danych osobowych i właściwych regulacji branżowych, w tym zasady minimalizacji danych, retencji, rozliczalności oraz obsługi praw podmiotów danych."
    },
    {
      "id": "NFR18",
      "description": "Powiadomienia o rezerwacjach, anulacjach i zmianach grafiku muszą być dostarczane terminowo i niezawodnie z mechanizmami ponawiania oraz monitorowaniem niepowodzeń dostarczenia."
    }
  ],
  "user_stories": [
    {
      "id": "US1",
      "description": "Jako użytkownik chcę przeglądać dostępne terminy z filtrowaniem po specjaliście, dacie, lokalizacji i typie usługi aby szybko znaleźć odpowiednią wizytę."
    },
    {
      "id": "US2",
      "description": "Jako użytkownik chcę zarezerwować wybrany dostępny termin aby otrzymać potwierdzoną wizytę bez ryzyka niejednoznacznego wyniku operacji."
    },
    {
      "id": "US3",
      "description": "Jako użytkownik chcę otrzymać jasne potwierdzenie rezerwacji wraz z najważniejszymi szczegółami aby wiedzieć kiedy i gdzie mam się stawić oraz co dalej zrobić."
    },
    {
      "id": "US4",
      "description": 'Jako użytkownik chcę widzieć czytelny powód niepowodzenia rezerwacji gdy termin stał się niedostępny aby móc szybko wybrać inny slot.'
    },
    {
      'id': 'US5',
      'description': 'Jako użytkownik chcę anulować własną rezerwację w dozwolonym oknie czasowym aby samodzielnie zarządzać swoimi wizytami.'
    },
    {
      'id': 'US6',
      'description': 'Jako użytkownik chcę przed anulowaniem widzieć zasady, limit czasowy i ewentualne konsekwencje aby podjąć świadomą decyzję.'
    },
    {
      'id': 'US7',
      'description': 'Jako użytkownik chcę złożyć wniosek o wyjątkowe anulowanie po upływie standardowego terminu aby mój uzasadniony przypadek mógł zostać rozpatrzony.'
    },
    {
      'id': 'US8',
      'description': 'Jako użytkownik chcę otrzymywać powiadomienia o utworzeniu rezerwacji, anulowaniu oraz zmianach dotyczących mojej wizyty aby być na bieżąco ze statusem sprawy.'
    },
    {
      'id': 'US9',
      'description': 'Jako specjalista chcę zarządzać własnym grafikiem dostępności aby udostępniać terminy zgodnie z moją rzeczywistą dyspozycyjnością.'
    },
    {
      'id': 'US10',
      'description': 'Jako specjalista chcę modyfikować grafik także wtedy gdy wpływa on na istniejące rezerwacje aby móc reagować na zmiany organizacyjne lub losowe.'
    },
    {
      'id': 'US11',
      'description': 'Jako specjalista chcę widzieć listę wizyt dotkniętych zmianą grafiku aby świadomie ocenić skutki planowanej modyfikacji.'
    },
    {
      'id': 'US12',
      'description': 'Jako administrator chcę konfigurować polityki anulacji zależnie od typu usługi, specjalisty lub czasu do wizyty aby dopasować zasady do potrzeb biznesowych.'
    },
    {
      'id': 'US13',
      'description': 'Jako administrator chcę definiować reguły wyjątków od konfliktów rezerwacji oraz nadawać uprawnienia do ich użycia aby zachować kontrolowaną elastyczność operacyjną.'
    },
    {
      'id': 'US14',
      'description': 'Jako administrator chcę mieć dostęp do raportów dotyczących wykorzystania grafiku, anulacji, wyjątków i no-show aby monitorować efektywność działania systemu.'
    },
    {
      'id': 'US15',
      'description': 'Jako pracownik wsparcia operacyjnego chcę obsługiwać zgłoszenia dotyczące sporów, wyjątkowych anulowań i zmian wizyt aby pomagać użytkownikom w sytuacjach niestandardowych.'
    },
    {
        'id': 'US16',
        'description': 'Jako pracownik wsparcia operacyjnego chcę wykonywać operacje wyjątkowe tylko po wymaganej autoryzacji i z uzasadnieniem aby zachować rozliczalność działań.'
    },
    {
      'id': 'US17',
      'description': 'Jako audytor lub administrator bezpieczeństwa chcę przeglądać niezmienialny ślad audytowy zmian rezerwacji, wyjątków i uprawnień aby móc wyjaśniać incydenty oraz spełniać wymagania zgodności.'
   ,
   }
  ]
}

