User stories:
[{"id": "US1", "description": "Jako pacjent chcę przeglądać kalendarz dostępności specjalisty z wizualnym oznaczeniem wolnych i zajętych terminów, aby szybko znaleźć odpowiedni termin wizyty bez konieczności kontaktu telefonicznego."}, {"id": "US2", "description": "Jako pacjent chcę dokonać rezerwacji wizyty w maksymalnie 3 krokach i otrzymać natychmiastowe potwierdzenie, aby mieć pewność że termin został zarezerwowany wyłącznie dla mnie."}, {"id": "US3", "description": "Jako pacjent chcę zobaczyć jasną informację o obowiązujących limitach czasowych anulowania przed finalizacją rezerwacji, aby świadomie podjąć decyzję i uniknąć niespodziewanych opłat."}, {"id": "US4", "description": "Jako pacjent chcę anulować rezerwację zgodnie z obowiązującą polityką czasową i otrzymać potwierdzenie anulowania, aby móc zarządzać swoim harmonogramem bez niepotrzebnych kosztów."}, {"id": "US5", "description": "Jako pacjent chcę otrzymać natychmiastowe powiadomienie (email lub SMS) gdy specjalista zmieni lub anuluje moją wizytę, aby móc niezwłocznie zaplanować alternatywny termin."}, {"id": "US6", "description": "Jako pacjent chcę przeglądać historię wszystkich moich rezerwacji wraz z ich statusami, aby mieć pełny wgląd w swoje wizyty i móc śledzić zmiany."}, {"id": "US7", "description": "Jako pacjent chcę zalogować się do systemu z użyciem uwierzytelniania wieloskładnikowego, aby moje dane medyczne i rezerwacje były chronione przed nieautoryzowanym dostępem."}, {"id": "US8", "description": "Jako specjalista chcę zarządzać swoim grafikiem dostępności, w tym definiować godziny pracy, długość wizyt i przerwy, aby pacjenci mogli rezerwować terminy zgodne z moją rzeczywistą dostępnością."}, {"id": "US9", "description": "Jako specjalista chcę modyfikować grafik dla terminów z istniejącymi rezerwacjami i automatycznie powiadamiać pacjentów o zmianie, aby móc elastycznie zarządzać swoim harmonogramem bez ręcznego informowania każdego pacjenta."}, {"id": "US10", "description": "Jako specjalista chcę przeglądać listę zaplanowanych wizyt z możliwością filtrowania i sortowania, aby efektywnie planować swój dzień pracy i przygotowywać się do wizyt."}, {"id": "US11", "description": "Jako specjalista chcę zintegrować system z moim zewnętrznym kalendarzem (Google Calendar lub iCal), aby uniknąć konfliktów między rezerwacjami systemowymi a innymi zobowiązaniami."}, {"id": "US12", "description": "Jako specjalista chcę otrzymywać powiadomienia o nowych rezerwacjach i anulowaniach w czasie rzeczywistym, aby być na bieżąco ze zmianami w moim grafiku bez konieczności ciągłego sprawdzania systemu."}, {"id": "US13", "description": "Jako administrator chcę konfigurować globalną politykę anulowania wizyt, w tym limity czasowe i opłaty za anulowanie, aby chronić przychody specjalistów i zapewnić spójność reguł w całym systemie."}, {"id": "US14", "description": "Jako administrator chcę ręcznie zatwierdzać wyjątki od polityki anulowania zgłoszone przez pacjentów, aby obsługiwać uzasadnione przypadki losowe przy zachowaniu pełnego zapisu w logu audytowym."}, {"id": "US15", "description": "Jako administrator chcę zarządzać kontami użytkowników i specjalistów, w tym tworzyć, edytować i dezaktywować konta oraz przypisywać role, aby utrzymać kontrolę nad dostępem do systemu."}, {"id": "US16", "description": "Jako administrator chcę przeglądać panel analityki z KPI takimi jak liczba rezerwacji, wskaźnik anulowań i przychody, aby podejmować decyzje biznesowe oparte na danych i monitorować kondycję platformy."}, {"id": "US17", "description": "Jako administrator chcę przeglądać kompletny log audytowy wszystkich operacji na rezerwacjach i grafikach, aby móc wykrywać nieprawidłowości, rozwiązywać spory i spełniać wymogi regulacyjne."}, {"id": "US18", "description": "Jako pacjent chcę złożyć wniosek o usunięcie moich danych osobowych z systemu, aby skorzystać z przysługującego mi prawa do bycia zapomnianym zgodnie z RODO."}, {"id": "US19", "description": "Jako nowy specjalista chcę przejść przez intuicyjny proces onboardingu umożliwiający konfigurację profilu i grafiku, aby szybko rozpocząć przyjmowanie rezerwacji bez potrzeby wsparcia technicznego."}, {"id": "US20", "description": "Jako pacjent chcę korzystać z systemu na urządzeniu mobilnym z pełną funkcjonalnością i dostępnością zgodną ze standardami WCAG 2.1 AA, aby móc rezerwować wizyty w dowolnym miejscu i czasie niezależnie od używanego urządzenia."}]

