    },
    {
      'id': 'US11',
      'description': 'Jako specjalista chcę widzieć które istniejące rezerwacje zostaną dotknięte zmianą grafiku aby świadomie potwierdzić skutki tej operacji.'
    },
    {
      'id': 'US12',
