[{"id": "US1", "description": "Jako nowy Użytkownik chcę zarejestrować się w systemie w maksymalnie 3 krokach (dane podstawowe, hasło, potwierdzenie email) aby móc szybko rozpocząć korzystanie z systemu bez zbędnych barier wejścia."}, {"id": "US2", "description": "Jako Użytkownik chcę zalogować się przez SSO (Google lub Apple) jednym kliknięciem aby uniknąć konieczności pamiętania hasła i przyspieszyć dostęp do systemu."}, {"id": "US3", "description": "Jako Użytkownik chcę przeglądać dostępne terminy wybranego specjalisty w widoku kalendarza aby szybko znaleźć odpowiadający mi termin bez znajomości szczegółów innych rezerwacji."}, {"id": "US4", "description": "Jako Użytkownik chcę zarezerwować wizytę w maksymalnie 3 krokach (wybór terminu, podanie danych, potwierdzenie) aby proces był szybki i nie wymagał podawania zbędnych informacji."}, {"id": "US5", "description": "Jako Użytkownik chcę otrzymać natychmiastowe potwierdzenie rezerwacji na ekranie oraz email z detalami wizyty aby mieć pewność, że rezerwacja została przyjęta."}, {"id": "US6", "description": "Jako Użytkownik chcę anulować rezerwację samodzielnie do 24 godzin przed wizytą jednym kliknięciem z jednym potwierdzeniem aby móc elastycznie zarządzać swoim harmonogramem bez kontaktu z obsługą."}, {"id": "US7", "description": "Jako Użytkownik chcę otrzymać czytelny komunikat (bez technicznego żargonu) gdy wybrany termin jest już zajęty lub gdy anulowanie jest niemożliwe ze względu na ograniczenie czasowe aby wiedzieć co zrobić w takiej sytuacji."}, {"id": "US8", "description": "Jako Użytkownik chcę otrzymać przypomnienie email lub SMS 24 godziny przed wizytą aby nie zapomnieć o zaplanowanej wizycie."}, {"id": "US9", "description": "Jako Użytkownik chcę być natychmiast powiadomiony emailem gdy specjalista zmodyfikuje lub odwoła moją rezerwację wraz z propozycją nowego terminu lub możliwością bezkosztowego anulowania aby móc podjąć odpowiednie działania."}, {"id": "US10", "description": "Jako Specjalista chcę skonfigurować swój grafik dostępności (godziny pracy, przerwy, urlopy, czas trwania wizyty, bufory między wizytami) aby system automatycznie prezentował użytkownikom tylko faktycznie dostępne terminy."}, {"id": "US11", "description": "Jako Specjalista chcę zalogować się do systemu z obowiązkowym MFA (TOTP lub SMS) aby moje konto i dane moich pacjentów były chronione przed nieautoryzowanym dostępem."}, {"id": "US12", "description": "Jako Specjalista chcę modyfikować swój grafik nawet gdy istnieją już rezerwacje w danym terminie, z automatycznym powiadomieniem dotkniętych użytkowników, aby móc elastycznie zarządzać swoją dostępnością w uzasadnionych przypadkach."}, {"id": "US13", "description": "Jako Specjalista chcę przeglądać listę moich nadchodzących rezerwacji z danymi kontaktowymi rezerwujących użytkowników aby móc przygotować się do wizyt i w razie potrzeby skontaktować się z pacjentem."}, {"id": "US14", "description": "Jako Administrator chcę przeglądać niemodyfikowalne logi audytowe wszystkich operacji w systemie (rezerwacje, anulowania, logowania, modyfikacje grafiku) aby móc wykrywać i analizować incydenty bezpieczeństwa oraz nieprawidłowości."}, {"id": "US15", "description": "Jako Administrator chcę mieć dostęp do dashboardu raportowego z kluczowymi metrykami biznesowymi (liczba rezerwacji, przychody z prowizji i subskrypcji, wskaźnik anulowań, aktywni użytkownicy) aby monitorować kondycję biznesu i podejmować decyzje operacyjne."}, {"id": "US16", "description": "Jako Administrator chcę ręcznie dopuścić wyjątek od reguły konfliktu rezerwacji z obowiązkowym uzasadnieniem zapisanym w logu audytowym aby obsłużyć szczególne przypadki biznesowe przy zachowaniu pełnej audytowalności."}, {"id": "US17", "description": "Jako Administrator chcę zarządzać planami subskrypcyjnymi specjalistów (podstawowy/premium) oraz konfiguracją prowizji od rezerwacji aby móc elastycznie dostosowywać model monetyzacji do potrzeb biznesowych."}, {"id": "US18", "description": "Jako Administrator chcę otrzymywać automatyczne alerty o anomaliach behawioralnych (masowe rezerwacje, wielokrotne nieudane logowania, próby nieautoryzowanego dostępu) aby móc szybko reagować na potencjalne zagrożenia bezpieczeństwa."}, {"id": "US19", "description": "Jako Specjalista chcę wybierać między planem subskrypcyjnym podstawowym a premium aby dopasować zakres funkcjonalności do moich potrzeb i możliwości finansowych, z jasnym przedstawieniem różnic między planami."}, {"id": "US20", "description": "Jako Użytkownik chcę przeglądać historię moich rezerwacji (przeszłych i nadchodzących) oraz zarządzać swoim profilem i preferencjami powiadomień aby mieć pełną kontrolę nad swoimi danymi i aktywnością w systemie."}]

