{
  "system_goal": "System ma umozliwiac szybka i skalowalna rezerwacje wizyt u specjalistow przy minimalnym tarciu dla uzytkownika, z obsluga anulowania, zarzadzania grafikiem i podstawowej monetyzacji. MVP powinno priorytetyzowac prostote procesu i szybkie wdrozenie, ale jednoczesnie zapewnic rozliczalnosc operacji, kontrole dostepu oraz deterministyczne zasady konfliktow i wyjatkow.",
  "roles": [
    {
      "name": "User",
      "permissions": [
        "register_account",
        "login",
        "manage_own_profile",
        "browse_available_slots",
        "create_own_booking",
        "view_own_bookings",
        "cancel_own_booking_within_policy",
        "submit_cancellation_reason_when_required"
      ]
    },
    {
      "name": "Specialist",
      "permissions": [
        "login_with_mfa",
        "manage_own_profile",
        "manage_own_schedule",
        "view_own_bookings",
        "modify_schedule_affecting_own_bookings",
        "request_or_apply_allowed_booking_conflict_exception_if_authorized",
        "view_minimum_required_user_data_for_own_appointments"
      ]
    },
    {
      "name": "Administrator",
      "permissions": [
        "login_with_mfa",
        "manage_users_and_roles",
        "configure_booking_and_cancellation_policies",
        "configure_allowed_conflict_exceptions",
        "view_audit_logs",
        "view_business_reports",
        "manage_system_settings",
        "perform_privileged_booking_or_schedule_interventions_with_audit"
      ]
    }
  ],
  "functional_requirements": [
    {
      "id": "FR1",
      "description": "System musi obslugiwac trzy role MVP: User, Specialist i Administrator, z kontrola dostepu oparta o role oraz ograniczeniem widocznosci danych do wlasnych rezerwacji, wlasnego grafiku lub jawnie autoryzowanych zasobow administracyjnych."
    },
    {
      "id": "FR2",
      "description": "System musi umozliwiac szybka rejestracje i logowanie uzytkownika przy minimalnym zestawie wymaganych danych dla User, przy czym Specialist i Administrator musza korzystac z MFA podczas logowania."
    },
    {
      "id": "FR3",
      "description": "System musi prezentowac liste najblizszych dostepnych terminow specjalisty w czytelnej formie mobilnej i desktopowej, bez koniecznosci przechodzenia przez rozbudowane filtry lub formularze."
    },
    {
      "id": "FR4",
      "description": "User musi moc utworzyc rezerwacje wybranego terminu w minimalnej liczbie krokow, a system musi natychmiast zwrocic jednoznaczny wynik operacji: potwierdzenie albo deterministyczny blad."
    },
    {
      "id": "FR5",
      "description": "System musi zapobiegac standardowym konfliktom rezerwacji tego samego terminu poprzez atomowa walidacje i zapis, tak aby rownolegle proby rezerwacji nie prowadzily do niespojnosci danych."
    },
    {
      "id": "FR6",
      "description": "Wyjatki od reguly braku konfliktu rezerwacji musza byc jawnie konfigurowalne przez Administratora, domyslnie wylaczone, wymagac dodatkowej autoryzacji dla operacji uprzywilejowanej oraz pozostawiac slad audytowy z powodem i tozsamoscia wykonawcy."
    },
    {
      "id": "FR7",
      "description": "System musi definiowac jednoznaczne stany rezerwacji co najmniej: booked, cancelled_by_user, cancelled_by_specialist, reschedule_required oraz completed, wraz z dozwolonymi przejsciami miedzy stanami."
    },
    {
      "id": "FR8",
      "description": "User musi moc anulowac wlasna rezerwacje tylko zgodnie z konfigurowalna polityka czasowa anulowania; system przed rozpoczeciem akcji musi jasno pokazac, czy anulowanie jest dozwolone, ograniczone lub wymaga uzasadnienia."
    },
    {
      "id": "FR9",
      "description": "Jesli polityka anulowania tego wymaga, system musi pobrac od User uzasadnienie anulowania w postaci krotkiego powodu; dla przypadkow niewymagajacych uzasadnienia proces anulowania ma pozostac uproszczony."
    },
    {
      "id": "FR10",
      "description": "Specialist musi moc zarzadzac swoim grafikiem przez dodawanie, usuwanie i modyfikowanie slotow dostepnosci, przy czym zmiany dotyczace istniejacych rezerwacji musza byc walidowane i zapisywane jako operacje audytowalne."
    },
    {
      "id": "FR11",
      "description": "Gdy Specialist zmieni grafik w sposob naruszajacy istniejaca rezerwacje, system musi oznaczyc taka rezerwacje stanem reschedule_required albo cancelled_by_specialist zgodnie z konfiguracja polityki oraz natychmiast poinformowac o tym User."
    },
    {
      "id": "FR12",
      "description": "System musi wyswietlac krotkie i jednoznaczne komunikaty o dostepnosci terminow, konflikcie, ograniczeniu anulowania i skutkach zmiany grafiku, bez ukrytej logiki i bez technicznego zargonu na glownych ekranach."
    },
    {
      "id": "FR13",
      "description": "Wszystkie operacje zmieniajace stan systemu, w tym logowanie, rezerwacja, anulowanie, zmiana grafiku, nadanie uprawnien i uzycie wyjatku konfliktu, musza byc zapisywane w niemodyfikowalnym logu audytowym z identyfikatorem aktora, czasem i wynikiem operacji."
    },
    {
      "id": "FR14",
      "description": "API systemu musi byc wersjonowane i zwracac spojny model odpowiedzi oraz deterministyczne kody bledow dla walidacji, autoryzacji, konfliktu terminu i naruszenia polityki anulowania."
    },
    {
      "id": "FR15",
      "description": "System musi stosowac szyfrowanie danych w transmisji i w spoczynku oraz ograniczac zakres danych osobowych widocznych dla Specialist do minimum niezbednego do realizacji wizyty."
    },
    {
      "id": "FR16",
      'description': 'System musi zapewniac podstawowe zabezpieczenia przed naduzyciami: silna polityke hasel, rate limiting logowania i operacji wrazliwych oraz wykrywanie anomalii dla masowych anulowan, masowych zmian grafiku i nietypowego uzycia wyjatkow konfliktu.'
    },
    {
      'id': 'FR17',
      'description': 'Administrator musi moc konfigurowac bez zmian kodu co najmniej: okno czasowe anulowania, wymagalnosc uzasadnienia anulowania, zasady reakcji na zmiane grafiku oraz katalog dopuszczalnych wyjatkow od konfliktow rezerwacji.'
    },
    {
      'id': 'FR18',
      'description': 'System musi dostarczac podstawowe raporty biznesowe obejmujace liczbe rezerwacji, anulacji, wykorzystanie grafikow specjalistow oraz dane potrzebne do rozliczen oplat, prowizji lub abonamentow.'
    },
    {
      'id': 'FR19',
      'description': 'Architektura rozwiazania musi wspierac skalowanie poziome warstwy aplikacyjnej i obsluge wielu specjalistow oraz uzytkownikow bez zmiany modelu funkcjonalnego MVP.'
    }
  ]
}

