{
  "acceptance_criteria": [
    {
      "id": "AC1",
      "given": "Uzytkownik nie jest zalogowany i nie ma konta",
      "when": "rozpoczyna rejestracje z procesu rezerwacji i podaje tylko wymagane minimum danych",
      "then": "konto zostaje utworzone bez zbednych pol, uzytkownik zostaje zalogowany i moze od razu kontynuowac rezerwacje"
    },
    {
      "id": "AC2",
      "given": "Uzytkownik chce umowic wizyte u specjalisty",
      "when": "otwiera widok dostepnych terminow specjalisty",
      "then": "system pokazuje najblizsze dostepne terminy domyslnie bez wymagania dodatkowych filtrow"
    },
    {
      "id": "AC3",
      "given": "Uzytkownik przeglada dostepne terminy i wybral slot",
      "when": "potwierdza rezerwacje w uproszczonym procesie",
      "then": "system finalizuje rezerwacje w kilku prostych krokach bez wymagania danych niepotrzebnych do MVP"
    },
    {
      "id": "AC4",
      "given": "Uzytkownik probuje zarezerwowac termin",
      "when": "operacja rezerwacji zostaje zakonczona",
      "then": "system natychmiast zwraca jednoznaczny wynik: potwierdzenie rezerwacji albo jasny kod bledu i powod niepowodzenia"
    },
    {
      "id": "AC5",
      "given": "Uzytkownik ma rezerwacje w systemie",
      "when": "otwiera liste swoich wizyt",
      "then": "widzi co najmniej rezerwacje nadchodzace i anulowane wraz z ich aktualnym statusem"
    },
    {
      "id": "AC6",
      "given": "Uzytkownik otwiera szczegoly swojej rezerwacji mozliwej do anulowania lub poza oknem anulacji",
      "when": "przechodzi do akcji anulowania",
      "then": "system przed potwierdzeniem jasno pokazuje czy anulowanie jest dozwolone wedlug aktualnej polityki oraz czy wymagane jest uzasadnienie"
    },
    {
      "id": "AC7",
      "given": "Uzytkownik ma rezerwacje spelniajaca warunki anulowania albo wyjatek dopuszczony regulami",
      "when": "potwierdza anulowanie i podaje uzasadnienie tylko jesli jest wymagane",
      "then": "rezerwacja otrzymuje status anulowana, slot zostaje zwolniony zgodnie z regulami, a uzytkownik dostaje natychmiastowe potwierdzenie albo jednoznaczny powod odmowy"
    },
    {
      "id": "AC8",
      "given": "Specjalista zmienia grafik w sposob wplywajacy na istniejaca rezerwacje uzytkownika",
      "when": "zmiana zostaje zapisana",
      "then": "powiazany uzytkownik otrzymuje natychmiastowa informacje o zmianie dotyczacej jego wizyty oraz nowym statusie lub koniecznosci wyboru innego terminu"
    },
    {
      "id": "AC9",
      "given": "Specjalista chce uzyskac dostep do funkcji zarzadzania grafikiem lub rezerwacjami",
      "when": "loguje sie do systemu",
      "then": "dostep jest przyznawany dopiero po poprawnym uwierzytelnieniu haslem i MFA"
    },
    {
      "id": "AC10",
      "given": "Specjalista jest poprawnie uwierzytelniony",
      "when": "dodaje lub usuwa sloty dostepnosci w swoim grafiku",
      "then": "system zapisuje zmiany tylko dla jego grafiku i blokuje utworzenie niedozwolonych konfliktow poza jawnymi wyjatkami zdefiniowanymi przez administratora"
    },
    {
      "id": "AC11",
      "given": "Specjalista modyfikuje grafik, a na objetych slotach istnieja juz rezerwacje",
      "when": "probuje zapisac zmiane",
      "then": "system pozwala na zmiane tylko zgodnie z politykami i regulami wyjatkow, oznacza dotkniete rezerwacje odpowiednim stanem oraz uruchamia wymagane powiadomienia i audyt"
    },
    {
      "id": "AC12",
      "given": "Specjalista przeglada dane rezerwacji przypisanej do swojej wizyty",
      'when': 'otwiera szczegoly pacjenta potrzebne do realizacji wizyty',
      'then': 'widzi tylko minimalny zakres danych niezbednych operacyjnie, bez danych nadmiarowych'
    },
    {
      'id': 'AC13',
      'given': 'Administrator ma uprawnienia konfiguracyjne',
      'when': 'zmienia polityke anulowania, w tym okno czasowe i wymagalnosc uzasadnienia',
      'then': 'nowe zasady sa stosowane bez zmian kodu dla kolejnych operacji oraz sa wersjonowane i audytowane'
    },
    {
      'id': 'AC14',
      'given': 'Administrator ma uprawnienia do zarzadzania regulami biznesowymi',
      'when': 'definiuje lub modyfikuje jawne wyjatki od konfliktow rezerwacji',
      'then': 'system zapisuje reguly w sposob mozliwy do przegladu, egzekwuje je przy operacjach konfliktowych i audytuje ich uzycie'
    },
    {
      'id': 'AC15',
      'given': 'W systemie wykonywana jest operacja krytyczna lub uprzywilejowana, taka jak zmiana grafiku z istniejacymi rezerwacjami, zmiana polityki, definicja wyjatku albo dostep do raportow administracyjnych',
      'when': 'operacja jest zatwierdzana',
      'then': 'system wymaga dodatkowej autoryzacji dla roli uprzywilejowanej oraz zapisuje kompletny wpis audytowy z aktorem, czasem, zakresem zmiany i wynikiem'
    },
    {
      'id': 'AC16',
      'given': 'Administrator otwiera modul raportowy MVP',
      'when': 'wybiera zakres czasu',
      'then': 'system prezentuje podstawowe raporty obejmujace liczbe rezerwacji, anulacji, oblozenie grafikow oraz przychody'
    },
    {
      'id': 'AC17',
      'given': 'QA Engineer lub integracja kliencka korzysta z logiki rezerwacji',
      'when': 'wykonywana jest dowolna operacja zmieniajaca stan rezerwacji',
      'then': 'system stosuje jednoznacznie zdefiniowany model stanow, dozwolonych przejsc oraz stabilne kody bledow dla przypadkow sukcesu i porazki'
    },
    {
      'id': 'AC18',
      'given': 'Dwoch uzytkownikow lub procesy rownoczesnie probuja zarezerwowac ten sam slot',
      'when': 'obie operacje docieraja niemal jednoczesnie do finalizacji',
        'then': 'dokladnie jedna rezerwacja moze zostac potwierdzona, a pozostale otrzymuja jednoznaczny blad konfliktu bez niespojnego stanu danych'
    }
  ]
}

