User stories:
[{"id": "US1", "description": "Jako Pacjent chcę zarejestrować się w systemie przez OAuth/SSO w maksymalnie 3 krokach, aby szybko uzyskać dostęp do funkcji rezerwacji bez zbędnych barier."}, {"id": "US2", "description": "Jako Pacjent chcę przeglądać dostępne terminy specjalisty w widoku kalendarza ładującym się poniżej 2 sekund, aby szybko znaleźć odpowiedni termin wizyty."}, {"id": "US3", "description": "Jako Pacjent chcę dokonać rezerwacji wizyty w maksymalnie 3 krokach z automatycznym uzupełnieniem moich danych z profilu, aby proces był szybki i wygodny."}, {"id": "US4", "description": "Jako Pacjent chcę otrzymać natychmiastowe potwierdzenie rezerwacji przez email i SMS, aby mieć pewność że wizyta została zarezerwowana poprawnie."}, {"id": "US5", "description": "Jako Pacjent chcę anulować wizytę z poziomu listy moich rezerwacji do 24 godzin przed terminem, aby móc zarządzać swoim harmonogramem bez kontaktu z obsługą."}, {"id": "US6", "description": "Jako Pacjent chcę opcjonalnie włączyć MFA na swoim koncie, aby zwiększyć bezpieczeństwo moich danych medycznych i osobowych."}, {"id": "US7", "description": "Jako Pacjent chcę przeglądać historię moich wizyt i rezerwacji, aby móc śledzić swoje wizyty i planować kolejne."}, {"id": "US8", "description": "Jako Specjalista chcę zarządzać swoim grafikiem dostępności (dodawać, modyfikować, usuwać sloty), aby kontrolować kiedy jestem dostępny dla pacjentów."}, {"id": "US9", "description": "Jako Specjalista chcę zmodyfikować termin istniejącej rezerwacji z podaniem uzasadnienia, aby system automatycznie powiadomił pacjenta o zmianie i zalogował operację."}, {"id": "US10", "description": "Jako Specjalista chcę logować się z obowiązkowym MFA, aby moje konto i dane pacjentów były chronione przed nieautoryzowanym dostępem."}, {"id": "US11", "description": "Jako Specjalista chcę zarządzać planem subskrypcyjnym premium z poziomu mojego panelu, aby uzyskać dostęp do wyróżnienia profilu i rozszerzonych statystyk."}, {"id": "US12", "description": "Jako Specjalista chcę przeglądać listę moich nadchodzących rezerwacji z danymi pacjentów, aby efektywnie planować swój czas pracy."}, {"id": "US13", "description": "Jako Administrator chcę przeglądać niemodyfikowalne logi audytowe wszystkich operacji w systemie, aby móc przeprowadzić forensykę w przypadku incydentu bezpieczeństwa."}, {"id": "US14", "description": "Jako Administrator chcę ręcznie zatwierdzać wyjątki od reguł rezerwacji (np. podwójne rezerwacje) z obowiązkowym uzasadnieniem logowanym w systemie, aby obsługiwać szczególne przypadki biznesowe."}, {"id": "US15", "description": "Jako Administrator chcę mieć dostęp do panelu analitycznego z KPI (liczba rezerwacji, przychody z prowizji, wskaźnik anulowań) od pierwszego dnia wdrożenia, aby monitorować kondycję biznesu."}, {"id": "US16", "description": "Jako Administrator chcę otrzymywać alerty w czasie rzeczywistym o anomaliach (masowe anulowania, ataki brute-force, podejrzane wzorce), aby szybko reagować na zagrożenia."}, {"id": "US17", "description": "Jako Administrator chcę konfigurować próg czasowy anulowania rezerwacji oraz czas wygaśnięcia sesji dla poszczególnych ról, aby dostosować reguły systemu do potrzeb biznesowych."}, {"id": "US18", "description": "Jako Inżynier QA chcę mieć dostęp do izolowanego środowiska testowego odwzorowującego produkcję z możliwością symulacji konfliktów rezerwacji, aby testować scenariusze brzegowe bez ryzyka dla danych produkcyjnych."}, {"id": "US19", "description": "Jako Product Manager chcę uruchamiać eksperymenty A/B na przepływach rezerwacji przez feature flags bez blokowania przez pełny cykl QA, aby szybko weryfikować hipotezy produktowe."}, {"id": "US20", "description": "Jako Pacjent chcę zapłacić za wizytę online podczas rezerwacji przez zintegrowaną bramkę płatności, aby cały proces rezerwacji był kompletny bez konieczności płatności na miejscu."}]

