User stories:
[{"id": "US1", "description": "Jako nowy użytkownik chcę zarejestrować się przez Google lub Facebook w maksymalnie 3 krokach (autoryzacja SSO, akceptacja polityki prywatności, potwierdzenie danych), aby szybko uzyskać dostęp do systemu bez konieczności tworzenia hasła."}, {"id": "US2", "description": "Jako zarejestrowany użytkownik chcę zalogować się jednym kliknięciem przez SSO (Google/Facebook), aby uniknąć wpisywania hasła i szybko przejść do przeglądania terminów."}, {"id": "US3", "description": "Jako specjalista chcę logować się z obowiązkowym MFA (TOTP lub SMS), aby moje konto i dane moich klientów były chronione przed nieautoryzowanym dostępem."}, {"id": "US4", "description": "Jako gość (niezalogowany użytkownik) chcę przeglądać dostępne terminy w widoku kalendarza bez konieczności rejestracji, aby ocenić ofertę przed podjęciem decyzji o rejestracji."}, {"id": "US5", "description": "Jako zalogowany użytkownik chcę zarezerwować wizytę w maksymalnie 3 krokach (wybór terminu, weryfikacja danych, płatność i potwierdzenie), aby proces był szybki i nie wymagał podawania zbędnych informacji."}, {"id": "US6", "description": "Jako użytkownik chcę otrzymać potwierdzenie rezerwacji na email w ciągu 60 sekund od jej dokonania, aby mieć pewność że wizyta została zarejestrowana w systemie."}, {"id": "US7", "description": "Jako użytkownik chcę anulować wizytę bezpośrednio z listy moich rezerwacji w 2 krokach (kliknięcie anuluj, potwierdzenie w dialogu), aby proces był prosty, a jednocześnie zabezpieczony przed przypadkowym anulowaniem."}, {"id": "US8", "description": "Jako użytkownik chcę otrzymać czytelny komunikat (bez żargonu technicznego) gdy próbuję anulować wizytę po upływie dozwolonego czasu, aby wiedzieć dlaczego anulowanie jest niemożliwe i jakie mam alternatywy."}, {"id": "US9", "description": "Jako specjalista chcę dodawać, modyfikować i usuwać sloty w moim grafiku, aby zarządzać dostępnością dla moich klientów zgodnie z moim harmonogramem pracy."}, {"id": "US10", "description": "Jako specjalista chcę być poinformowany o wpływie modyfikacji slotu na istniejące rezerwacje i potwierdzić zmianę dodatkowym krokiem, aby świadomie zarządzać konsekwencjami zmian w grafiku dla moich klientów."}, {"id": "US11", "description": "Jako użytkownik chcę otrzymać powiadomienie email gdy specjalista zmodyfikuje termin mojej wizyty, aby móc podjąć decyzję o akceptacji nowego terminu lub anulowaniu rezerwacji."}, {"id": "US12", "description": "Jako specjalista lub administrator chcę zezwolić na wyjątkowe double-booking z obowiązkowym uzasadnieniem tekstowym i dodatkowym potwierdzeniem, aby obsłużyć szczególne przypadki przy zachowaniu pełnej ścieżki audytu."}, {"id": "US13", "description": "Jako specjalista w planie płatnym chcę mieć dostęp do panelu analitycznego z wykresami liczby rezerwacji, wskaźnika anulowań i przychodów z możliwością eksportu CSV, aby podejmować decyzje biznesowe oparte na danych."}, {"id": "US14", "description": "Jako administrator chcę mieć dostęp do dashboardu biznesowego z kluczowymi metrykami (rezerwacje, przychody, churn, aktywni specjaliści) z filtrowaniem po datach, aby monitorować kondycję platformy bez dostępu do danych osobowych użytkowników."}, {"id": "US15", "description": "Jako administrator chcę otrzymywać alerty email w ciągu 5 minut od wykrycia anomalii bezpieczeństwa (5+ nieudanych logowań w 10 minut, 10+ anulowań w 1 godzinę przez jednego użytkownika), aby szybko reagować na potencjalne nadużycia."}, {"id": "US16", "description": "Jako użytkownik chcę zresetować hasło przez link wysłany na mój email (ważny 15 minut), aby odzyskać dostęp do konta w przypadku zapomnienia hasła bez konieczności kontaktu z supportem."}, {"id": "US17", "description": "Jako użytkownik chcę wyeksportować moje dane osobowe lub usunąć konto z anonimizacją danych w ciągu 72 godzin od złożenia żądania, aby korzystać z przysługujących mi praw wynikających z RODO."}, {"id": "US18", "description": "Jako użytkownik w planie premium chcę opcjonalnie włączyć przypomnienia SMS i email o nadchodzących wizytach, aby nie zapominać o zaplanowanych spotkaniach bez narzucania mi powiadomień których nie chcę."}, {"id": "US19", "description": "Jako administrator chcę konfigurować limit czasowy anulowania rezerwacji (domyślnie 24h przed wizytą) oraz wysokość prowizji od rezerwacji, aby dostosować reguły biznesowe platformy bez konieczności angażowania zespołu technicznego."}, {"id": "US20", "description": "Jako członek zespołu QA chcę mieć dostęp do izolowanego środowiska testowego odtwarzającego konfigurację produkcyjną oraz do pełnej dokumentacji reguł biznesowych i wyjątków, aby pisać deterministyczne testy automatyczne pokrywające wszystkie scenariusze brzegowe."}]

