User stories:
[{"id": "US1", "description": "Jako Gość chcę zarezerwować wizytę u specjalisty bez zakładania konta (podając tylko email) aby szybko umówić się na wizytę i otrzymać token potwierdzający na email, który umożliwi mi zarządzanie rezerwacją."}, {"id": "US2", "description": "Jako Pacjent chcę zarejestrować się w systemie w maksymalnie 2 krokach (email i hasło) aby szybko uzyskać dostęp do pełnej funkcjonalności rezerwacji bez zbędnych formalności."}, {"id": "US3", "description": "Jako Pacjent chcę przeglądać dostępne terminy wybranego specjalisty w widoku kalendarza ładowanym w maksymalnie 2 sekundy aby sprawnie wybrać odpowiedni termin wizyty."}, {"id": "US4", "description": "Jako Pacjent chcę zarezerwować wizytę w maksymalnie 3 krokach (wybór terminu, potwierdzenie danych, finalizacja) aby proces rezerwacji był szybki i intuicyjny, a ja otrzymał potwierdzenie na email."}, {"id": "US5", "description": "Jako Pacjent chcę anulować rezerwację do 24 godzin przed wizytą aby móc zarządzać swoim harmonogramem, przy czym system poinformuje mnie o konsekwencjach anulowania po przekroczeniu limitu czasowego."}, {"id": "US6", "description": "Jako Pacjent chcę otrzymywać powiadomienia email o potwierdzeniu rezerwacji, przypomnieniu 24h przed wizytą oraz o wszelkich zmianach dokonanych przez specjalistę aby być na bieżąco z moimi wizytami."}, {"id": "US7", "description": "Jako Pacjent chcę mieć możliwość włączenia MFA dla swojego konta aby zwiększyć bezpieczeństwo moich danych osobowych i historii wizyt, przy czym MFA nie jest obowiązkowe dla tej roli."}, {"id": "US8", "description": "Jako Specjalista chcę zarządzać własnym grafikiem dostępności (dodawanie, usuwanie i modyfikacja slotów) aby precyzyjnie kontrolować swój harmonogram pracy i dostępność dla pacjentów."}, {"id": "US9", "description": "Jako Specjalista chcę być powiadamiany i wymagać potwierdzenia przed modyfikacją slotu z istniejącą rezerwacją aby świadomie zarządzać zmianami wpływającymi na pacjentów, którzy automatycznie otrzymają propozycję nowego terminu."}, {"id": "US10", "description": "Jako Specjalista chcę logować się do systemu z obowiązkowym MFA aby moje konto i dane moich pacjentów były chronione przed nieautoryzowanym dostępem, nawet kosztem dodatkowego kroku logowania."}, {"id": "US11", "description": "Jako Specjalista chcę wybrać plan subskrypcyjny (Basic/Premium) podczas onboardingu aby dopasować funkcjonalność systemu do moich potrzeb i rozumieć koszty korzystania z platformy."}, {"id": "US12", "description": "Jako Admin chcę manualnie weryfikować i aktywować konta specjalistów aby zapewnić wiarygodność specjalistów w systemie i chronić pacjentów przed nieautoryzowanymi osobami podającymi się za specjalistów."}, {"id": "US13", "description": "Jako Admin chcę zatwierdzać wyjątki od reguły konfliktu rezerwacji z obowiązkowym podaniem uzasadnienia aby elastycznie zarządzać szczególnymi przypadkami przy zachowaniu pełnej audytowalności każdego wyjątku."}, {"id": "US14", "description": "Jako Admin chcę przeglądać niemodyfikowalny log audytowy wszystkich operacji na rezerwacjach i grafiku aby móc wykrywać nadużycia, rozwiązywać spory i spełniać wymogi compliance."}, {"id": "US15", "description": "Jako Admin chcę mieć dostęp do dashboardu raportowego z danymi o rezerwacjach, przychodach i konwersji odświeżanymi co maksymalnie 5 minut aby podejmować decyzje biznesowe oparte na aktualnych danych."}, {"id": "US16", "description": "Jako Admin chcę otrzymywać alerty o anomaliach bezpieczeństwa (masowe anulowania, blokady kont, logowania z nieznanych lokalizacji) aby szybko reagować na potencjalne zagrożenia i nadużycia w systemie."}, {"id": "US17", "description": "Jako Admin chcę konfigurować limit czasowy anulowania rezerwacji (domyślnie 24h) oraz parametry modelu prowizyjnego aby dostosowywać polityki biznesowe bez konieczności zmian w kodzie aplikacji."}, {"id": "US18", "description": "Jako Admin chcę zarządzać feature flags dla testów A/B przez panel administracyjny bez deploymentu kodu aby szybko eksperymentować z funkcjonalnościami i mierzyć ich wpływ na konwersję."}, {"id": "US19", "description": "Jako Tester chcę mieć dostęp do dedykowanego środowiska testowego wiernie odwzorowującego produkcję oraz precyzyjnych kryteriów akceptacji dla każdego wymagania aby skutecznie weryfikować poprawność systemu przed każdym wdrożeniem."}, {"id": "US20", "description": "Jako Użytkownik z niepełnosprawnością chcę korzystać z interfejsu zgodnego z WCAG 2.1 AA aby móc w pełni obsługiwać system rezerwacji przy użyciu technologii asystujących, takich jak czytniki ekranu."}]

