User stories:
[{"id": "US1", "description": "Jako Gość chcę przeglądać dostępne terminy specjalistów bez konieczności zakładania konta, aby ocenić ofertę przed rejestracją."}, {"id": "US2", "description": "Jako Gość chcę zarejestrować konto pacjenta przez e-mail lub konto społecznościowe (OAuth2) w maksymalnie 2 minuty, aby szybko uzyskać dostęp do funkcji rezerwacji."}, {"id": "US3", "description": "Jako Pacjent chcę zarezerwować wizytę u specjalisty w maksymalnie 3 krokach (wybór terminu, potwierdzenie danych, finalizacja), aby proces był szybki i bezproblemowy."}, {"id": "US4", "description": "Jako Pacjent chcę otrzymać natychmiastowe potwierdzenie rezerwacji e-mailem po jej dokonaniu, aby mieć pewność że wizyta została zarejestrowana."}, {"id": "US5", "description": "Jako Pacjent chcę anulować wizytę bez podawania szczegółowego uzasadnienia, przy czym system informuje mnie o obowiązującej polityce anulowania i ewentualnych opłatach, abym mógł podjąć świadomą decyzję."}, {"id": "US6", "description": "Jako Pacjent chcę przeglądać historię moich rezerwacji i ich statusy, aby mieć pełny wgląd w swoje wizyty."}, {"id": "US7", "description": "Jako Pacjent chcę zarządzać preferencjami powiadomień (e-mail, SMS) i otrzymywać przypomnienia o wizycie 24h i 1h przed terminem, aby nie zapomnieć o zaplanowanej wizycie."}, {"id": "US8", "description": "Jako Specjalista chcę zarejestrować konto i skonfigurować podstawowy grafik w mniej niż 5 minut bez blokowania dostępu przez weryfikację tożsamości, aby szybko rozpocząć przyjmowanie rezerwacji."}, {"id": "US9", "description": "Jako Specjalista chcę dodawać, edytować i usuwać sloty w moim grafiku, aby elastycznie zarządzać swoją dostępnością."}, {"id": "US10", "description": "Jako Specjalista chcę modyfikować slot, na który istnieje aktywna rezerwacja, przy czym system wymaga potwierdzenia akcji i automatycznie powiadamia pacjenta o zmianie, abym mógł zarządzać grafikiem bez ręcznego kontaktowania się z pacjentem."}, {"id": "US11", "description": "Jako Specjalista chcę mieć dostęp do własnych statystyk (liczba wizyt, wskaźnik wypełnienia grafiku, przychody), aby monitorować efektywność swojej praktyki."}, {"id": "US12", "description": "Jako Specjalista chcę korzystać z planu freemium z możliwością przejścia na plan premium (30-dniowy trial bez karty kredytowej), aby ocenić wartość zaawansowanych funkcji przed podjęciem decyzji o subskrypcji."}, {"id": "US13", "description": "Jako Specjalista z włączonym MFA chcę logować się do systemu przy użyciu drugiego składnika uwierzytelniania, aby moje konto i dane pacjentów były odpowiednio chronione."}, {"id": "US14", "description": "Jako Admin chcę zarządzać rolami i uprawnieniami użytkowników (przypisywanie, modyfikacja, odbieranie ról), przy czym każda zmiana jest rejestrowana w logu audytowym, aby utrzymać kontrolę nad dostępem do systemu."}, {"id": "US15", "description": "Jako Admin chcę przeglądać niemodyfikowalny dziennik audytowy wszystkich operacji krytycznych (rezerwacje, anulowania, modyfikacje grafiku, logowania, płatności), aby móc przeprowadzić forensykę w przypadku incydentu."}, {"id": "US16", "description": "Jako Admin chcę konfigurować politykę anulowania rezerwacji (okno czasowe, opłaty za późne anulowanie) dla całego systemu lub dla konkretnych specjalistów, aby dostosować zasady do modelu biznesowego."}, {"id": "US17", "description": "Jako Admin chcę otrzymywać alerty w czasie rzeczywistym o anomaliach bezpieczeństwa (wielokrotne nieudane logowania, masowe anulowania, podejrzane wzorce), aby szybko reagować na potencjalne zagrożenia."}, {"id": "US18", "description": "Jako Admin chcę mieć dostęp do dashboardu analitycznego z kluczowymi metrykami biznesowymi (liczba rezerwacji, przychody, wskaźnik anulowań, aktywni specjaliści, nowi użytkownicy) od dnia 1 produkcji, aby monitorować kondycję biznesu."}, {"id": "US19", "description": "Jako Pacjent chcę wyeksportować moje dane osobowe i historię rezerwacji oraz mieć możliwość usunięcia konta z anonimizacją danych, aby korzystać z przysługujących mi praw wynikających z RODO."}, {"id": "US20", "description": "Jako Admin chcę włączyć dla konkretnego specjalisty tryb rezerwacji grupowej (slot wieloosobowy z określonym limitem miejsc), aby system obsługiwał wyjątki od standardowej logiki zapobiegania konfliktom rezerwacji."}]

